<?php if (!defined('BASEPATH')) exit('No direct script access allowed');class Workinprogress extends CI_Controller {    private $limit = 20;    public $companyid = '';    public $userid = '';    public $order = [];    public function __construct() {        parent::__construct();        $this->load->helper('xssclean');        $this->load->model(CNFCOMPANY . 'workinprogressmodel');        $this->load->model(CNFCOMPANY . 'orderentrymodel');        $this->load->model( 'commonmodel');        fnIfCheckUserLoggedIn();        $ArrUserLoggedInfo = fnGetUserLoggedInfo('1');        $this->companyid      = $ArrUserLoggedInfo['companyid'];        $this->userid = $ArrUserLoggedInfo['id'];        $this->order = array('eid' => 'desc');    }    function fnTest() {        $ArrRes = $this->workinprogressmodel->fnList();        die;        echo json_encode(array('e' => $ArrRes['enquiery'], 'o' => $ArrRes['order']));        $this->load->view(CNFCOMPANY . 'testview');    }    /*******************************Data Tables START******************************/    var $column_order =  array('','e.isriorcode', 'e.datecreated','brandname','stylenamerefno','orderenqrefno','','','','','','','e.status');    var $column_search = array('e.isriorcode', 'e.datecreated','brandname','stylenamerefno','orderenqrefno','e.status');    public function datatables_wip_qry() {        $this->db->select('e.id,e.datecreated,e.dateupdated,e.isriorno,e.companyid,e.reqforisrior,e.stylenamerefno,orderenqrefno,        e.exporderqty,e.orderstatus,e.pcsorset,e.brandbuyerid,e.isriorcode,e.merchantid,brandname,buyername,e.status');        $this->db->from(KN_ORDER_ENQUIRY.' AS e');        $this->db->where('e.companyid',$this->companyid);        $this->db->join(KN_MASTER_BRANDS.' AS br','br.id = e.brandbuyerid');        // commented by myself  regards new brand form       // $this->db->join(KN_MASTER_BUYER.' AS by','br.buyerid = by.id');        $this->db->where('e.status !=','3');        $i = 0;        foreach ($this->column_search as $item) {            if($_POST['search']['value']) {                if(validateDate($_POST['search']['value'])) {                    $_POST['search']['value'] = date('Y-m-d',strtotime($_POST['search']['value']));                }                if($i===0) {                    $this->db->group_start();                    $this->db->like($item, $_POST['search']['value']);                }                else {                    $this->db->or_like($item, $_POST['search']['value']);                }                if(count($this->column_search) - 1 == $i) {                    $this->db->group_end();                }            }            $i++;        }        //echo '<pre>'; print_r($_POST);        if(isset($_POST['order'])) {            $this->db->order_by($this->column_order[$_POST['order']['0']['column']], $_POST['order']['0']['dir']);        }        else if(isset($this->order)) {            $order = $this->order;            //echo '<pre>'; print_r($order);            $this->db->order_by(key($order), $order[key($order)]);        }    }    public function wipDatatables() {        $this->datatables_wip_qry();        if($_POST['length'] != -1)            $this->db->limit($_POST['length'], $_POST['start']);        $query = $this->db->get();        return $query->result();    }    public function count_filtered() {        $this->datatables_wip_qry();        $query = $this->db->get();        return $query->num_rows();    }    public function count_all() {        $this->db->from(KN_ORDER_ENQUIRY.' AS e');        $this->db->where('e.companyid',$this->companyid);        $this->db->join(KN_MASTER_BRANDS.' AS br','br.id = e.brandbuyerid');        // commented by myself  regards new brand form       // $this->db->join(KN_MASTER_BUYER.' AS by','br.buyerid = by.id');        $this->db->where('e.status !=','3');        return $this->db->count_all_results();    }    /********************************Data Tables ENDS***************************/    function enquirydetail() {        $VarHashId = $this->uri->segment('4');        echo '<pre>';        print_r(base64_decode(urldecode($VarHashId)));        die('');    }    public function wip_detail() {        $VarPoNo = urldecode($this->uri->segment('5'));        $VarId = $this->uri->segment('4');        if(!empty($VarPoNo) && !empty($VarId)) {            $this->load->model(CNFCOMPANY.'mcadrequestmodel');            $this->load->model('commonmodel');            $ArrFromSecondTbl = $this->orderentrymodel->getFromSecondTbl($VarId,$this->companyid);            $ArrPoNo = $ArrAllPoNo = [];            if(!empty($ArrFromSecondTbl->jsondatagrid)) {                $ArrExtraDetails = json_decode($ArrFromSecondTbl->jsondatagrid,true);                foreach ($ArrExtraDetails as $secondTable) {                    $ArrAllPoNo[] = $secondTable[4];                }                //Check if PO Number is duplicate                if(count($ArrAllPoNo) !== count(array_unique($ArrAllPoNo))) {                    $ArrPoNo = get_keys_for_duplicate_values($ArrAllPoNo);                }                else {                    $ArrPoNo = $ArrAllPoNo;                }                //echo '<pre>'; print_r($ArrPoNo); die('die');            }            $ArrFromFourthTblRes = $this->orderentrymodel->getFromDeliveryScheduleSixthTbl($VarId, $this->companyid);            $ArrFromFourthTbl = $ArrFourthTblSeparate = [];            if(!empty($ArrFromFourthTblRes->jsondatagrid)) {                $ArrFromFourthTbl = json_decode($ArrFromFourthTblRes->jsondatagrid,true);                //echo '<pre>'; print_r($ArrFromFourthTbl); die('die');                foreach ($ArrFromFourthTbl as $item) {                    $ArrFourthTblGrid[] = array($item[0], $item[1], $item[2], $item[3], $item[4], $item[5], $item[6],                        $item[7], $item[8], $item[9], $item[10], $item[11]);                    $ArrFourthTblSeparate[$item[3]]['modeofshipment'] = $item[6];                    $ArrFourthTblSeparate[$item[3]]['shipementdate'] = date('d-m-Y', strtotime($item[7]));                    $ArrFourthTblSeparate[$item[3]]['exfactorydate'] = '';                    $ArrFourthTblSeparate[$item[3]]['loadingportcity'] = $item[8];                    $ArrFourthTblSeparate[$item[3]]['loadingcountry'] = $item[9];                    $ArrFourthTblSeparate[$item[3]]['destiportcity'] = $item[10];                    $ArrFourthTblSeparate[$item[3]]['desticountry'] = $item[11];                }            }                $VarCommonOrderEntryInfo        = $this->commonmodel->commonBasicInfoOrderEntry($VarId, $this->companyid);                $ArrData['ArrCompanyInfo']      = $VarCommonOrderEntryInfo['ArrCompanyInfo'];                $ArrData['ArrMerchant']         = $VarCommonOrderEntryInfo['ArrMerchant'];                $ArrData['ArrTeamInfo']         = $VarCommonOrderEntryInfo['ArrTeamInfo'];                $ArrData['ArrOrderEnqData']     = $VarCommonOrderEntryInfo['ArrOrderEnqData'];                $ArrData['ArrBB']               = $VarCommonOrderEntryInfo['ArrBB'];                $ArrData['ArrOrderCommonData']  = $VarCommonOrderEntryInfo['ArrOrderCommonData'];                $ArrData['VarId']               = $VarId;                $ArrData['ArrPo']               = $ArrPoNo;                $ArrData['VarPoNo']             = $VarPoNo;                $ArrData['ArrFromSecondTbl']    = $ArrFromSecondTbl;                $ArrData['ArrFourthTblSeparate']= $ArrFourthTblSeparate;                $ArrData['ArrModeOfShipment']   = unserialize(ORDERMODEOFSHIPMENT);                $ArrPortInfo                    = $this->commonmodel->fnGetAllTableInfo(KN_MASTER_PORT . ' AS p', 'p.id,p.portname,p.portcity',                    array('p.status' => 1, 'p.companyid' => $this->companyid), 3);                $ArrPortAndCity = [];                if(!empty($ArrPortInfo)) {                    foreach ($ArrPortInfo as $item) {                        $ArrPortAndCity[] = $item['portname'] . ', ' . $item['portcity'];                    }                }                $ArrData['ArrPortAndCity'] = $ArrPortAndCity;                $ArrPoNoIds = urldecode($this->uri->segment('6'));                $ArrData['ArrPoNoIds'] = $ArrPoNoIds;                $ArrRes = $this->workinprogressmodel->getCommonPonumberData($VarId,$this->companyid,$ArrPoNoIds);                if(!empty($ArrRes)) {                    $ArrData['Commonstatus'] = $ArrRes[0]->commonstatus;                    $ArrData['Remarks'] = $ArrRes[0]->remarks;                    $ArrData['Fullpart'] = $ArrRes[0]->fullpart;                }                $ArrEachPoNoData = $this->workinprogressmodel->getEachPonoStatus($VarId,$this->companyid,explode(',',$ArrPoNoIds));                if(!empty($ArrEachPoNoData)) {                    $ArrData['ArrEachPoNoData'] = $ArrEachPoNoData[0];                }                else {                }            $this->load->view(CNFCOMPANY . 'workinprocess_detailpage', $ArrData);        }    }    public function updateEachPonoStatus() {        $VarFrom = xssclean($this->input->post('rfrom'));        if($VarFrom == 1) {            $VarReferenceId = xssclean($this->input->post('refid'));            $VarCommonss = xssclean($this->input->post('commonss'));            $VarFullpart = xssclean($this->input->post('fp'));            $VarRemarks = xssclean($this->input->post('rem'));            $ArrModeofshipment = json_decode(xssclean($this->input->post('ms')),true);            $ObjModeofshipment = xssclean($this->input->post('ms'));            $VarShipmentdate = xssclean($this->input->post('sd'));            $VarExfactorydate = '';            $VarLoadingport = xssclean($this->input->post('lp'));            $VarDestiport = xssclean($this->input->post('dp'));            $VarShipmentstatus = xssclean($this->input->post('ss'));            $VarDatetime = date('Y-m-d H:i:s');            $Res = $this->workinprogressmodel->saveEachPonoStatus($ArrModeofshipment,$ObjModeofshipment,$VarShipmentdate,$VarExfactorydate,$VarLoadingport,$VarDestiport,                $VarShipmentstatus,$VarCommonss,$VarFullpart,$VarRemarks,$VarDatetime,$VarReferenceId,$this->companyid,$this->userid);            echo json_encode(array('errCode'=>1));        }    }    //@TODO send to archives feature/*    public function sendToArchives() {        //rFrom=1&id="+idJson+"&s="+d        $VarFrom = xssclean($this->input->post('rFrom'));        if($VarFrom == 1) {            $ArrId = xssclean($this->input->post('id'));            $Status = xssclean($this->input->post('cs'));        }    }*/}